with cleaned as (select id, account_id, txn_type, amount, txn_time, merchant, is_flagged, trim(txn_type) as clean_txn_type from transactions where txn_time >= to_timestamp('2023-07-08 06:00:00') and merchant is not null), prev_events as (select *, lag(txn_time) over (partition by txn_type order by txn_time, id) as prev_txn_time from cleaned), with_gaps as (select *, case when prev_txn_time is null or txn_time > prev_txn_time + interval '7' day then 1 else 0 end as new_group_flag from prev_events), islands as (select id, account_id, txn_type, txn_time, is_flagged, clean_txn_type, sum(new_group_flag) over (partition by txn_type order by txn_time, id rows between unbounded preceding and current row) as session_no from with_gaps) select account_id, approx_percentile(session_no, 0.5) as session_no_p50, sort_array(collect_set(txn_type)) as txn_type_list, max(txn_time) as last_seen from islands group by account_id order by session_no_p50 nulls first
